#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU,
# including SKUs with no movements that day (e.g. SKU-9 from the catalog).
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3); seen[$1] = 1 }
     BEGIN { seen["SKU-9"] = 1 }
     END { for (sku in seen) print sku, net[sku] + 0 }' \
    movements.log | sort > stock.txt
